public class PriceCalculator
{
    private static Dictionary<string, Discount> _cache;
    private readonly IDiscountRepository _repo;

    public PriceCalculator(IDiscountRepository repo) { _repo = repo; }

    public decimal Calculate(Cart cart)
    {
        if (_cache == null)
        {
            _cache = new Dictionary<string, Discount>();
            foreach (var d in _repo.LoadAll())
                _cache[d.Code] = d;
        }
        return ApplyDiscounts(cart);
    }

    private decimal ApplyDiscounts(Cart cart)
    {
        var total = cart.Items.Sum(i => i.Price * i.Quantity);
        foreach (var code in cart.Codes)
        {
            var d = _cache[code.ToUpper()];
            total -= total * d.Percent / 100m;   // line 42
        }
        return total;
    }
}
